    std::vector<A> t3(250);
    std::vector<A> t4(25600);
    for (int i = 0; i < 512; i++) for (int j = 0; j < 50; j++) t4[j * 512 + i] = saved.relu_5[i * 50 + j];
    std::vector<A> t5(2560);
    for (int i = 0; i < 512; i++) for (int j = 0; j < 5; j++) t5[j * 512 + i] = dY[i * 5 + j];
    gemm(t5.data(), t4.data(), t3.data(), 5, 50, 512);
    std::vector<A> t6(5);
