    std::vector<A> t7(25600);
    relu_backward(t1.data(), saved.relu_5_bit.data(), t7.data(), 25600);
    std::vector<A> t8(25600);
    std::vector<A> t9(2500);
    for (int i = 0; i < 50; i++) for (int j = 0; j < 50; j++) t9[j * 50 + i] = w[10][i * 50 + j];
